css:
.loader { display: inline-flex; align-items: flex-end; justify-content: center; gap: calc(var(--loader-size) * .12); width: var(--loader-size); height: calc(var(--loader-size) * .5); }
.loader span { width: calc(var(--loader-size) * .18); height: calc(var(--loader-size) * .18); border-radius: 9999px; background: var(--loader-color); animation: twBounce var(--loader-speed) infinite; }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * .15); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * .3); }
@keyframes twBounce { 0%, 100% { transform: translateY(-45%); animation-timing-function: cubic-bezier(.8, 0, 1, 1); } 50% { transform: translateY(0); animation-timing-function: cubic-bezier(0, 0, .2, 1); } }
